// Python-style repr() helpers for strings, ints and dict-like pairs.

export function reprStr(s) {
  // Match CPython's quote selection: prefer ', use " only when the string
  // contains ' but no ".
  let quote = "'";
  if (s.includes("'") && !s.includes('"')) {
    quote = '"';
  }
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + ch;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (code < 32 || code === 127) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  return out + quote;
}

export function reprValue(v) {
  if (typeof v === 'string') return reprStr(v);
  if (typeof v === 'number' || typeof v === 'bigint') return String(v);
  if (v === null || v === undefined) return 'None';
  return String(v);
}

// Render an ordered list of [key, value] pairs like a Python dict.
export function reprDict(pairs) {
  const items = pairs.map(([k, v]) => `${reprValue(k)}: ${reprValue(v)}`);
  return '{' + items.join(', ') + '}';
}

