// Bidirectional dictionary re-implemented from the observable behaviour of
// Python's bidict: forward lookup key -> value, inverse lookup value -> key,
// insertion order preserved, and uniqueness enforced on both sides.

import { reprDict, reprValue } from './pyrepr.mjs';

export class ValueDuplicationError extends Error {
  constructor(value) {
    super(`ValueDuplicationError: ${reprValue(value)}`);
    this.name = 'ValueDuplicationError';
  }
}

export class Bidict {
  constructor() {
    // Ordered list of [key, value] pairs; plain objects index both directions.
    this._entries = [];
    this._fwd = Object.create(null); // key -> index into _entries
    this._bwd = new MapLike();       // value -> index into _entries
  }

  set(key, value) {
    const k = String(key);
    if (this._fwd[k] !== undefined) {
      const idx = this._fwd[k];
      const oldValue = this._entries[idx][1];
      this._bwd.remove(oldValue);
      this._entries[idx][1] = value;
      this._bwd.set(value, idx);
      return;
    }
    if (this._bwd.has(value)) {
      throw new ValueDuplicationError(value);
    }
    this._fwd[k] = this._entries.length;
    this._bwd.set(value, this._entries.length);
    this._entries.push([k, value]);
  }

  get(key) {
    const idx = this._fwd[String(key)];
    if (idx === undefined) {
      throw new Error(`KeyError: ${reprValue(String(key))}`);
    }
    return this._entries[idx][1];
  }

  // Inverse view: b.inv[value] -> key
  get inv() {
    return { get: (value) => this.inverseGet(value) };
  }

  inverseGet(value) {
    const idx = this._bwd.get(value);
    if (idx === undefined) {
      throw new Error(`KeyError: ${reprValue(value)}`);
    }
    return this._entries[idx][0];
  }

  toString() {
    return `bidict(${reprDict(this._entries)})`;
  }
}

// Tiny numeric-keyed index over an array backing store. Values are integers
// in this program, so a plain object with a type-tagged key is sufficient.
class MapLike {
  constructor() {
    this._slots = Object.create(null);
  }

  _tag(value) {
    return (typeof value) + ':' + String(value);
  }

  set(value, idx) {
    this._slots[this._tag(value)] = idx;
  }

  get(value) {
    return this._slots[this._tag(value)];
  }

  has(value) {
    return this._slots[this._tag(value)] !== undefined;
  }

  remove(value) {
    delete this._slots[this._tag(value)];
  }
}

