// Minimal argparse-compatible parser: required options only, --name value and
// --name=value forms, int/str types, argparse-style errors on stderr with
// exit code 2.

import { basename } from 'node:path';
import { reprStr } from './pyrepr.mjs';

function progName() {
  return basename(process.argv[1] || 'test8.mjs');
}

function fail(message, spec) {
  const usage =
    'usage: ' +
    progName() +
    ' [-h] ' +
    spec.map((s) => `--${s.name} ${s.name.toUpperCase()}`).join(' ');
  process.stderr.write(usage + '\n');
  process.stderr.write(`${progName()}: error: ${message}\n`);
  process.exit(2);
}

function parseIntLike(text, optName, spec) {
  const trimmed = text.replace(/^\s+|\s+$/g, '');
  if (!/^[+-]?\d+$/.test(trimmed)) {
    fail(`argument --${optName}: invalid int value: ${reprStr(text)}`, spec);
  }
  return parseInt(trimmed, 10);
}

// spec: [{ name, type: 'str' | 'int', required: true }]
export function parseArgs(spec) {
  const values = {};
  const seen = new Set();
  const byName = new Map(spec.map((s) => [s.name, s]));
  const argv = process.argv.slice(2);

  for (let i = 0; i < argv.length; i++) {
    let token = argv[i];
    if (token === '-h' || token === '--help') {
      const usage =
        'usage: ' +
        progName() +
        ' [-h] ' +
        spec.map((s) => `--${s.name} ${s.name.toUpperCase()}`).join(' ');
      process.stdout.write(usage + '\n');
      process.exit(0);
    }
    if (!token.startsWith('--')) {
      fail(`unrecognized arguments: ${token}`, spec);
    }
    let name = token.slice(2);
    let inline = null;
    const eq = name.indexOf('=');
    if (eq !== -1) {
      inline = name.slice(eq + 1);
      name = name.slice(0, eq);
    }
    const opt = byName.get(name);
    if (!opt) {
      fail(`unrecognized arguments: ${token}`, spec);
    }
    let raw;
    if (inline !== null) {
      raw = inline;
    } else {
      if (i + 1 >= argv.length) {
        fail(`argument --${name}: expected one argument`, spec);
      }
      raw = argv[++i];
    }
    values[name] = opt.type === 'int' ? parseIntLike(raw, name, spec) : raw;
    seen.add(name);
  }

  const missing = spec.filter((s) => s.required && !seen.has(s.name));
  if (missing.length > 0) {
    fail(
      'the following arguments are required: ' +
        missing.map((s) => `--${s.name}`).join(', '),
      spec
    );
  }
  return values;
}

