// Entry point — mirrors test8.py behaviour exactly.

import { parseArgs } from './lib/argparse.mjs';
import { Bidict } from './lib/bidict.mjs';

const args = parseArgs([
  { name: 'k1', type: 'str', required: true },
  { name: 'v1', type: 'int', required: true },
  { name: 'k2', type: 'str', required: true },
  { name: 'v2', type: 'int', required: true },
  { name: 'k3', type: 'str', required: true },
  { name: 'v3', type: 'int', required: true },
]);

// 复杂的多步操作
const b = new Bidict();
b.set(args.k1, args.v1);
b.set(args.k2, args.v2);
b.set(args.k3, args.v3);
console.log(String(b));

// 通过不同方式访问
console.log(b.get(args.k1));
console.log(b.inv.get(args.v2));
console.log(b.inv.get(args.v3));

// 更新一个值
b.set(args.k1, 999);
console.log(String(b));

